// TH18 v1.00a st03bs.ecl::Boss/Boss1, source 8-141 (non-spell, slot0 HP2800 / timeout2100).
// Target card t0 is the phase start; 120-frame shell buffer replaces the source prelude
// (Boss wait101 + dialogWait). Source Boss1 t0 = card ~122; first source wait80 -> first fire ~202.
const TIME_LIMIT: int = 2222;
const SOURCE_LIMIT: int = 2100;
const TH18_SHARD: int = 512;

// Source 104-130 EX chain after ANIM/OFFSCREEN:
//   VELTIME60 3.2 -> 0.03 along current angle;
//   VELTIME30 -> 2.0 toward player+E;
//   VELTIME30 -> 0.03 along current angle;
//   VELTIME30 -> 2.0 toward player+F+0.08726646*RANDF2.
// E/F are configuration-time values shared by the outer group; the +/-5deg is per bullet.
// The ANIM birth stage is omitted by policy; its -4*initial-speed displacement is kept by sh_dist.
xformdef BOSS1_SHOT(e: angle, f: angle) {
    // Source OFFSCREEN(200,b=0); five handler-end reentries inside 200 -> 195 protected starts.
    offscreen_keep(195);
    set_accel(at_effect((0.03fx-$self_speed)/60fx));
    wait(60);
    set_angle(at_effect(aim_player()+e));
    set_accel(at_effect((2fx-$self_speed)/30fx));
    wait(30);
    set_accel(at_effect((0.03fx-$self_speed)/30fx));
    wait(30);
    set_angle(at_effect(aim_player()+f));
    turn(at_spawn((((rand(65536)-32768)*910)/32768) as angle)); // 0.087266rad nearest BAM, RANDF2
    set_accel(at_effect((2fx-$self_speed)/30fx));
    wait(30);
    stop_fx();
}

// Source 99-140 Boss1_at. Each call is one full B*C ring:
// outer B times advances E/F by 2pi/B and the ring base D by (2pi/B)/C; inner C times emits
// one angle step 2pi/C. Batched as C ring paths per source outer iteration, preserving order.
sub boss1_at(a: angle, c: int) {
    var rank: int = global(GVAR_RANK);
    var b: int = 16;                    // diffI(16,28,42,48)
    if rank == 1 { b = 28; }
    if rank == 2 { b = 42; }
    if rank == 3 { b = 48; }
    var d: int = rand(65536)-32768;     // RANDRAD
    var e: int = rand(65536)-32768;     // RANDRAD
    var f: int = e+(a as int);
    var step_b: int = 65536/b;          // 2pi/B
    var step_d: int = (65536/b)/c;      // (2pi/B)/C
    sh_reset(0);
    sh_sprite(0, TH18_SHARD, 4);        // etSprite(10,4)
    sh_ring(0, 1);                      // etAim(0,3): fixed ring
    sh_speed(0, 3.2fx, 0fx);            // etSpeed(3.2,1.0); M1 uses the first speed
    sh_dist(0, -12.8fx);                // ANIM a1: position -= 4*3.2 at birth
    for h in 0..b {
        // Source 120-125: increments happen before the first inner emission.
        e = e+step_b;
        f = f+step_b;
        d = d+step_d;
        var g: int = d;                 // validRad(G); angle consumers take low 16 bits
        sh_count(0, c, 1);              // source inner loop count C=I0
        sh_angle(0, (g as angle), 0deg);
        sh_xform(0, BOSS1_SHOT((e as angle), (f as angle)));
        sh_fire(0);
    }
}

// Boss common entry B:26-28: hurtbox40/hitbox48 and moveLimit(0,128,280,64).
// moveRand(60,4,0.7): source speed slot keeps interpolation mode0, speed(k)=0.7*(1-k/60).
// Bounds x[-140,140], y[96,160]; direction inner tests use x+-70, y112/144 (movement.md).
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.7fx*((60-k) as fx)/60fx; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source signed unit random * pi, integer BAM representation.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad -> nearest BAM bounds.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

async sub pattern() {
    wait(120);                          // training shell buffer
    var until: int = $frame+SOURCE_LIMIT;
    var rank: int = global(GVAR_RANK);
    var w: int = 120;                   // !E/!N 120, !H 100, !LO 80 (bare-value stack)
    if rank == 2 { w = 100; }
    if rank == 3 { w = 80; }
    set_self_int(0, 60);                // movement idle until the first source moveRand
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    wait(80);                           // source Boss1 wait80
    var i0: int = 12;
    var a: angle = 90deg;               // F0 = 1.570796
    loop {
        if $frame >= until { return; }
        boss1_at(a, i0);
        a = -a;
        card_wait(w);
        card_move_rand();
        card_wait(w);
        if i0 < 16 { i0 = i0+1; }       // source 92-93: increment only while I0 < 16
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);                   // source setHitbox(48,48), ordinary circle uses half
    set_hurtbox(20fx);                  // source setHurtbox(40,40)
    phase_begin(0, pattern, TIME_LIMIT, 2800); // source slot0 HP2800 / 2100
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 128fx, 19800, 0, 0, 0, boss_main); // source movePos(0,128), lifeSet(19800)
    loop { wait(600); }
}
